INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 4), 'reading', 4, 41, 'cloze_passage_shared', 'r4_p4', 41, 'Chỗ trống (1)', NULL, '林一正的孩子快要出生了，他覺得現在的家太小了，所以他在自己的公司附近(1)。那裡有很多商店，而且離房子走路五分鐘的地方，(2)。房子對面還有一個小公園，以後他和太太(3)，雖然那裡的房子很貴，讓(4)，但是林一正覺得沒關係，因為(5)，林一正相信太太一定也很喜歡這間房子。', NULL, '[{"label":"A","text":"買了一間房子"},{"label":"B","text":"就有一家大醫院"},{"label":"C","text":"林一正沒花多少錢"},{"label":"D","text":"林一正花了不少錢"},{"label":"E","text":"那裡的生活很方便"},{"label":"F","text":"可以常常帶孩子到公園玩"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 4), 'reading', 4, 42, 'cloze_passage_shared', 'r4_p4', 42, 'Chỗ trống (2)', NULL, '林一正的孩子快要出生了，他覺得現在的家太小了，所以他在自己的公司附近(1)。那裡有很多商店，而且離房子走路五分鐘的地方，(2)。房子對面還有一個小公園，以後他和太太(3)，雖然那裡的房子很貴，讓(4)，但是林一正覺得沒關係，因為(5)，林一正相信太太一定也很喜歡這間房子。', NULL, '[{"label":"A","text":"買了一間房子"},{"label":"B","text":"就有一家大醫院"},{"label":"C","text":"林一正沒花多少錢"},{"label":"D","text":"林一正花了不少錢"},{"label":"E","text":"那裡的生活很方便"},{"label":"F","text":"可以常常帶孩子到公園玩"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
