INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 4), 'reading', 4, 45, 'cloze_passage_shared', 'r4_p4', 45, 'Chỗ trống (5)', NULL, '林一正的孩子快要出生了，他覺得現在的家太小了，所以他在自己的公司附近(1)。那裡有很多商店，而且離房子走路五分鐘的地方，(2)。房子對面還有一個小公園，以後他和太太(3)，雖然那裡的房子很貴，讓(4)，但是林一正覺得沒關係，因為(5)，林一正相信太太一定也很喜歡這間房子。', NULL, '[{"label":"A","text":"買了一間房子"},{"label":"B","text":"就有一家大醫院"},{"label":"C","text":"林一正沒花多少錢"},{"label":"D","text":"林一正花了不少錢"},{"label":"E","text":"那裡的生活很方便"},{"label":"F","text":"可以常常帶孩子到公園玩"}]'::jsonb, 4) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 4), 'reading', 5, 46, 'passage_mcq', NULL, 46, '明麗最後要說的意思是什麼？', NULL, '明麗的朋友都覺得明麗總是開心地過生活，大家從來沒有看過她傷心或生氣。有一次，我問她是怎麼辦到的，她回答我：「每天一早醒來，我都有兩個選擇，可以選擇壞心情，討厭自己的生活；也可以選擇好心情，喜愛自己的生活。如果是你，不會選第二個嗎？」', NULL, '[{"label":"A","text":"想太多事情對自己沒用"},{"label":"B","text":"心情好壞可以自己決定"},{"label":"C","text":"早睡早起的人一定快樂"},{"label":"D","text":"生活進步的方法有很多"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 4), 'reading', 5, 47, 'passage_mcq', NULL, 47, '這篇文章在談什麼？', NULL, '你怎麼處理那些已經不再看的書呢？直接丟掉？送給別人？還是賣給書店？現代網路的進步，使賣書變得更容易。於是有些人就利用網路開店賣舊書，把賺來的錢分給需要的人，有時也將舊書送到鄉下或山裡的學校，這樣的話，不但可以保護環境，還可以讓更多的人有機會讀書。', NULL, '[{"label":"A","text":"用家中舊書換新書的方法"},{"label":"B","text":"上網看書才不會用太多紙"},{"label":"C","text":"學會賣書可以賺更多的錢"},{"label":"D","text":"把不要的書變成有用的書"}]'::jsonb, 3) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 4), 'reading', 5, 48, 'passage_mcq', NULL, 48, '從參加比賽到比賽結束，順文是怎麼想的？', NULL, '順文歌唱得很好，上個月，她參加了一個唱歌比賽，為了能把歌唱好，她每天都練習五個小時，非常辛苦。沒想到，就在比賽開始的前一天，順文不小心感冒了，大家都非常擔心這會對她有不好的影響。結果，比賽的成績真的不太好。但順文卻一點也不難過，她告訴我們，能參加比賽就已經很幸福了，比賽讓她學到很多。', NULL, '[{"label":"A","text":"她只想拿第一名"},{"label":"B","text":"這是一次很好的經驗"},{"label":"C","text":"成績不好都是因為生病"},{"label":"D","text":"為了比賽，健康已經不重要"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 4), 'reading', 5, 49, 'passage_mcq', NULL, 49, '作者覺得，為什麼有人會覺得上班時間不夠？', NULL, '一天工作八小時，有的人覺得剛剛好，有的人覺得不夠用，會出現這樣的不同，我覺得是因為沒有好好安排時間的關係。下面兩點建議可以給大家參考：第一，試試看申請兩個手機號碼，一個只用在工作上，另一個用來聯繫家人或朋友，上班時間只接工作用的電話。第二，每天進辦公室或下班以前，可以留半小時到一小時，收、寄電子郵件，這樣的話，就不會因為經常得花時間寫郵件，影響了自己的工作。', NULL, '[{"label":"A","text":"他們太喜歡找家人、朋友聊天兒"},{"label":"B","text":"他們常常忘了回重要的電子郵件"},{"label":"C","text":"他們可能經常工作到一半就得停下來"},{"label":"D","text":"他們不太常注意自己上、下班的時間"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 4), 'reading', 5, 50, 'passage_mcq', NULL, 50, '老闆聽了同學們最想問的問題以後，他怎麼回答？', NULL, '上週，校長邀請了一位大公司的老闆到學校來，跟同學們談一談他的成功經驗，講完以後，還讓同學們問問題。因為那位老闆講得太好，同學們的問題一個接著一個，大家最想知道的就是：要怎麼做才能快一點兒成功？我本來以為，大老闆會教大家一些實際的方法，但他卻告訴我們：「做好現在應該做的，你們就已經成功了」。', NULL, '[{"label":"A","text":"好好學習就可以了"},{"label":"B","text":"必頇像他一樣努力才行"},{"label":"C","text":"要知道什麼事情不應該做"},{"label":"D","text":"得學會馬上聽懂老闆說的話"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
