INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 5), 'reading', 4, 41, 'cloze_passage_shared', 'r5_p4', 41, 'Chỗ trống (1)', NULL, '昨天晚上我覺得很不舒服，(41)，所以很早就睡覺了。今天早上起來，(42)。我去看病，醫生說我感冒了，給了我一些藥，(43)要多休息，多喝水，才會快點好。這幾天的天氣一會兒熱，一會兒冷，(44)。我要(45)，不要再感冒了。', NULL, '[{"label":"A","text":"還告訴我"},{"label":"B","text":"頭有點兒痛"},{"label":"C","text":"很容易生病"},{"label":"D","text":"覺得很舒服"},{"label":"E","text":"更不舒服了"},{"label":"F","text":"多注意自己的身體"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
