INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 5), 'reading', 4, 45, 'cloze_passage_shared', 'r5_p4', 45, 'Chỗ trống (5)', NULL, '昨天晚上我覺得很不舒服，(41)，所以很早就睡覺了。今天早上起來，(42)。我去看病，醫生說我感冒了，給了我一些藥，(43)要多休息，多喝水，才會快點好。這幾天的天氣一會兒熱，一會兒冷，(44)。我要(45)，不要再感冒了。', NULL, '[{"label":"A","text":"還告訴我"},{"label":"B","text":"頭有點兒痛"},{"label":"C","text":"很容易生病"},{"label":"D","text":"覺得很舒服"},{"label":"E","text":"更不舒服了"},{"label":"F","text":"多注意自己的身體"}]'::jsonb, 5) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 5), 'reading', 5, 46, 'passage_mcq', NULL, 46, '這篇文章說了什麼內容？', NULL, '曾有一項調查發現，很多員工生病的時候不敢請假，因為他們擔心老闆會不高興，覺得他們沒有責任感。有人認為，員工會這麼想是公司的責任。一個好的公司應該能照顧員工，而不是讓他們拿健康去換錢。因此，讓員工有幸福感，應該是未來企業努力的方向。', NULL, '[{"label":"A","text":"老闆應該給員工多一點兒假"},{"label":"B","text":"常關心別人的人更有責任感"},{"label":"C","text":"對公司有意見要勇敢說出來"},{"label":"D","text":"照顧身體比認真工作更重要"}]'::jsonb, 3) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 5), 'reading', 5, 47, 'passage_mcq', NULL, 47, '在改善健康方面，下面哪一個是作者的建議？', NULL, '如果你每天都覺得身體很累，有一份報告或許可以告訴你原因。這份報告提到了下面幾種可能：不愛運動、水喝得不夠多、總是把事情想得太壞、不吃早餐、吃太多沒營養的食物等。以上幾點，只要簡單思考一下自己符合了幾項，再試著做出一些改變，想讓自己更健康一點也不難。', NULL, '[{"label":"A","text":"要培養運動的好習慣"},{"label":"B","text":"想要吃什麼就吃什麼"},{"label":"C","text":"平常應該多做點好事"},{"label":"D","text":"吃早餐以後不要喝水"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 5), 'reading', 5, 48, 'passage_mcq', NULL, 48, '這個故事告訴了我們什麼事？', NULL, '從前有一個地方很久都不下雨，人們不管怎麼求雨都沒有用。有一次，他們從很遠的地方，請來一位有智慧的老人，希望他可以幫幫忙。老人在附近走了走、看了看，然後告訴他們，請蓋一間小屋，讓他住進去三天，三天當中，他任何人都不見。結果，三天後真的下雨了。大家都問他是怎麼做到的，他只回答，只要自己的心安靜了，外面就安靜了，所以下雨了。', NULL, '[{"label":"A","text":"先照顧自己，才能幫助別人"},{"label":"B","text":"想改變環境，就先改變心情"},{"label":"C","text":"年輕人應該要學會尊敬老人"},{"label":"D","text":"聰明的人知道什麼時候下雨"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 5), 'reading', 5, 49, 'passage_mcq', NULL, 49, '這段話說了下面哪件事？', NULL, '說到錢，每個人對它的想法、使用方式和重視程度都不一樣。有人說：「錢是沒有性格的，它在誰的手上就像誰」。這句話說得很有道理，人們因為對錢的看法不同，而選擇不同的生活方式。比方說，有的人喜歡看到銀行裡的數字不斷增加，所以每天努力工作，很少花錢；有的人覺得錢只要夠用就好，不必太在意工作，因為「自己的時間」，也是一種看不到的「錢」。', NULL, '[{"label":"A","text":"錢比什麼都重要"},{"label":"B","text":"錢可以解決所有事情"},{"label":"C","text":"人人有自己對錢的看法"},{"label":"D","text":"錢得放在銀行裡才有價值"}]'::jsonb, 2) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 5), 'reading', 5, 50, 'passage_mcq', NULL, 50, '作者對在電影院裡吃東西的行為怎麼看？', NULL, '以前，電影院的門口常常出現一個牌子，要觀眾別帶外面買的食物進去，如果想吃東西，只能買電影院裡賣的食物。後來，新聞說，觀眾其實可以拒絕配合這些電影院的規矩。說到這個問題，我認為，電影院的要求不是沒有道理，因為電影結束以後，他們還得打掃那些垃圾。其次，如果有人帶了一些有奇怪味道的食物進電影院，也很容易影響其他看電影的人。', NULL, '[{"label":"A","text":"應該要避免吃有特別味道的東西"},{"label":"B","text":"覺得吃什麼東西都是個人的自由"},{"label":"C","text":"認為電影院的要求沒有任何道理"},{"label":"D","text":"看電影的人都有責任要打掃垃圾"}]'::jsonb, 0) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
INSERT INTO public.tocfl_questions (paper_id, section, part_number, question_number, question_type, group_key, order_index, prompt_hanzi, prompt_image_path, passage_hanzi, audio_path, options, correct_index) VALUES ((SELECT id FROM public.tocfl_papers WHERE band = 'A' AND paper_number = 5), 'listening', 1, 1, 'picture_stim_text_choice', NULL, 1, '他們在哪裡？', '/tocfl/A/listening/5/images/q01_stim.png', NULL, '/tocfl/A/listening/5/audio/q01.mp3', '[{"label":"A","text":"銀行"},{"label":"B","text":"教室"},{"label":"C","text":"郵局"}]'::jsonb, 1) ON CONFLICT (paper_id, section, question_number) DO UPDATE SET question_type = EXCLUDED.question_type, group_key = EXCLUDED.group_key, order_index = EXCLUDED.order_index, prompt_hanzi = EXCLUDED.prompt_hanzi, prompt_image_path = EXCLUDED.prompt_image_path, passage_hanzi = EXCLUDED.passage_hanzi, audio_path = EXCLUDED.audio_path, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index;
